CREATE OR REPLACE FUNCTION public.biz_report_deadline_ready(_kind text,_pk text,_y integer,_p integer) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE m jsonb;o timestamptz;d timestamptz;c timestamptz;
BEGIN m:=public.biz_any_milestones(_kind,_pk,_y,_p);o:=(m->>'open')::timestamptz;d:=(m->>'due')::timestamptz;c:=(m->>'late_close')::timestamptz;RETURN o IS NOT NULL AND d IS NOT NULL AND c IS NOT NULL AND o<=d AND d<c;END $$;
REVOKE ALL ON FUNCTION public.biz_report_deadline_ready(text,text,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_report_deadline_ready(text,text,integer,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.biz_report_target_version(_user uuid,_year integer,_period_kind text,_period integer,_mode text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT v.target_version_id FROM public.biz_documents d JOIN public.biz_document_versions v ON v.id=d.official_version_id WHERE d.user_id=_user AND d.kind='report' AND d.period_kind=_period_kind AND d.year=_year AND d.period=_period),(SELECT official_version_id FROM public.biz_annual_goals WHERE user_id=_user AND year=_year)) $$;
DO $patch$
DECLARE f text;sig text;marker text;
BEGIN
 FOREACH sig IN ARRAY ARRAY['private.biz_report_actual_range(uuid,uuid,date,date,text)','public.biz_report_metrics(uuid,integer,text,integer,text)','public.biz_dashboard_read(integer,text,integer,uuid,uuid,text)','private.biz_dashboard_global_read(integer,text,integer,uuid,uuid,text)','public.biz_dashboard_data(integer,text,integer,uuid,uuid,text)'] LOOP
 SELECT pg_get_functiondef(sig::regprocedure) INTO f;IF position('BEGIN' IN f)=0 THEN RAISE EXCEPTION 'Unexpected function shape: %',sig;END IF;f:=overlay(f placing E'BEGIN\n _mode:=\x27official\x27;' from position('BEGIN' IN f) for 5);EXECUTE f;END LOOP;
 SELECT pg_get_functiondef('public.biz_report_cycle_config_of(uuid,date)'::regprocedure) INTO f;marker:='RETURN jsonb_build_object(''cycle'',''month'',''workdays'',null,''scope'',''default'');';IF position(marker IN f)=0 THEN RAISE EXCEPTION 'Cycle resolver changed';END IF;
 f:=replace(f,marker,'RETURN jsonb_build_object(''cycle'',CASE WHEN _at >= DATE ''2026-11-02'' THEN ''week'' ELSE ''month'' END,''workdays'',null,''scope'',''default'',''effective_from'',CASE WHEN _at >= DATE ''2026-11-02'' THEN ''2026-11-02'' END);');EXECUTE f;
 SELECT pg_get_functiondef('public.biz_any_phase(text,text,integer,integer,timestamp with time zone)'::regprocedure) INTO f;f:=overlay(f placing E'BEGIN\n IF _kind=\x27report\x27 AND NOT public.biz_report_deadline_ready(_kind,_pk,_y,_p) THEN RETURN \x27none\x27; END IF;' from position('BEGIN' IN f) for 5);EXECUTE f;
 FOREACH sig IN ARRAY ARRAY['public.biz_document_save(uuid,integer,text,text,jsonb,boolean,jsonb,jsonb)','public.biz_document_first_submit_guard()'] LOOP
 SELECT pg_get_functiondef(sig::regprocedure) INTO f;marker:=CASE WHEN sig LIKE '%save(%' THEN 'phase_:=public.biz_any_phase' ELSE 'phase:=public.biz_any_phase' END;IF position(marker IN f)=0 THEN RAISE EXCEPTION 'Submission guard changed: %',sig;END IF;f:=replace(f,marker,'IF d.kind=''report'' AND NOT public.biz_report_deadline_ready(d.kind,d.period_kind,d.year,d.period) THEN RAISE EXCEPTION ''Cần hoàn tất ba mốc deadline Báo cáo trước khi nộp.''; END IF; '||marker);EXECUTE f;END LOOP;
 SELECT pg_get_functiondef('public.biz_report_cycle_save(text,uuid,uuid,text,date,jsonb)'::regprocedure) INTO f;marker:='IF _effective_from IS NULL OR _effective_from < ''2020-01-01'' THEN RAISE EXCEPTION ''Ngày hiệu lực không hợp lệ.''; END IF;';IF position(marker IN f)=0 THEN RAISE EXCEPTION 'Cycle save changed';END IF;
 f:=replace(f,marker,marker||' IF _cycle=''week'' AND (extract(isodow FROM _effective_from)<>1 OR _effective_from < DATE ''2026-11-02'') THEN RAISE EXCEPTION ''Chu kỳ Tuần mới phải từ Thứ Hai, không hồi tố trước 02/11/2026.''; END IF; IF NOT public.biz_report_deadline_ready(''report'',_cycle,CASE WHEN _cycle=''week'' THEN to_char(_effective_from,''IYYY'')::int ELSE extract(year FROM _effective_from)::int END,CASE _cycle WHEN ''week'' THEN to_char(_effective_from,''IW'')::int WHEN ''day'' THEN (_effective_from-make_date(extract(year FROM _effective_from)::int,1,1))+1 WHEN ''month'' THEN extract(month FROM _effective_from)::int ELSE extract(quarter FROM _effective_from)::int END) THEN RAISE EXCEPTION ''Cần hoàn tất cả ba mốc deadline trước khi áp dụng chu kỳ Báo cáo.''; END IF;');EXECUTE f;
 SELECT pg_get_functiondef('public.biz_deadline_save(jsonb)'::regprocedure) INTO f;marker:='FOR k,r IN SELECT * FROM jsonb_each(_data) LOOP';IF position(marker IN f)=0 THEN RAISE EXCEPTION 'Deadline save changed';END IF;
 f:=replace(f,marker,'SELECT data INTO old FROM public.biz_deadline_config WHERE id=true FOR UPDATE; '||marker||' IF k IN (''report_day'',''report_week'',''report_month'',''report_quarter'') AND r IS DISTINCT FROM old->k THEN FOREACH ms IN ARRAY ARRAY[''open'',''due'',''late_close''] LOOP IF r->ms IS NULL OR r->ms=''null''::jsonb OR (k IN (''report_day'',''report_week'') AND r->ms->>''offset_days'' IS NULL) OR (k IN (''report_month'',''report_quarter'') AND r->ms->>''day'' IS NULL) THEN RAISE EXCEPTION ''Báo cáo cần đủ ba mốc mở nộp, hạn cuối và đóng nộp bù.''; END IF; END LOOP; END IF;');f:=replace(f,'v_open >= v_due','v_open > v_due');EXECUTE f;
END $patch$;
COMMENT ON FUNCTION public.biz_report_deadline_ready(text,text,integer,integer) IS 'Authoritative three-milestone readiness gate; incomplete report schedules never permit first submission. Historical configuration rows and submitted documents are unchanged.';